namespace sv_9261dfc13dc14b4c85ceaa95acbc48e8.Services;

/// <summary>
/// Scoped (per-circuit) service that holds the currently selected warehouse
/// and notifies all subscribers when the selection changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new("wh-a", "Warehouse A – East"),
        new("wh-b", "Warehouse B – West"),
        new("wh-c", "Warehouse C – Central"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public Warehouse CurrentWarehouse =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId);

    /// <summary>Raised on the calling thread – subscribers must call InvokeAsync / StateHasChanged themselves.</summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == _currentWarehouseId) return;
        if (AvailableWarehouses.All(w => w.Id != warehouseId)) return;

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public sealed record Warehouse(string Id, string Name);

namespace sv_9261dfc13dc14b4c85ceaa95acbc48e8.Services;

/// <summary>
/// Scoped (per-circuit) service that polls for low-stock alerts on a timer.
/// Any component can subscribe to <see cref="OnAlertCountChanged"/> to be
/// notified when new data arrives, enabling cross-component updates without
/// parent-child relationships.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Raised whenever the alert count is refreshed.
    /// Subscribers should call InvokeAsync + StateHasChanged.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Polling starts on the first subscriber and stops when the last unsubscribes.
    /// </summary>
    public async Task StartPollingAsync()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            await RefreshAsync();
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>Call when a component that was polling is disposed / leaves the page.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        await NotifySubscribersAsync();
    }

    private async Task NotifySubscribersAsync()
    {
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    /// <summary>
    /// When the warehouse changes, immediately refresh so every subscriber
    /// sees data for the new warehouse right away.
    /// </summary>
    private async void HandleWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            await RefreshAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

